<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue';
import { Head, usePage } from '@inertiajs/vue3';
import { ArrowUp, ArrowUpRight, ArrowLeft, ArrowRight, Plus, Search, Sparkles, LayoutGrid, MessageSquare, ChevronDown, ChevronRight, UsersRound, Check, CheckCheck, Clock3, Link2, FolderOpen, MoreHorizontal, Settings2, ShieldCheck, X, Paperclip, PanelRight, PanelLeft, LogOut, RefreshCw, CircleHelp, ChartNoAxesCombined, TrendingUp, Wallet, Layers3, Database, Globe2, ExternalLink, CircleCheck, AlertCircle, LoaderCircle, Square, FileText, Download, Trash2, Pencil, CheckCircle2, Copy, Send, Zap, Activity, SlidersHorizontal, CalendarClock, Cloud, LockKeyhole, Menu, Eye, Bell, Circle, BookOpen, LayoutDashboard, ArrowDownToLine, Unplug } from 'lucide-vue-next';
import BiCatalog from '../Components/BiCatalog.vue';
import AccountSecurity from '../Components/AccountSecurity.vue';
import UsersManagement from '../Components/UsersManagement.vue';
import BiOperations from '../Components/BiOperations.vue';
import AiPlanUsage from '../Components/AiPlanUsage.vue';
import ArtifactPreview from '../Components/ArtifactPreview.vue';
import ApprovalReview from '../Components/ApprovalReview.vue';
import RefreshInspector from '../Components/RefreshInspector.vue';
import ProjectPreviewPane from '../Components/ProjectPreviewPane.vue';
import {appUrl,localPath} from '../lib/urls';
import {createRequestGuard} from '../lib/async-response';
import {createProjectDrafts} from '../lib/project-drafts';
import {createSingleFlight} from '../lib/single-flight';
import { marked } from 'marked';
import DOMPurify from 'dompurify';
import Echo from 'laravel-echo';
import Pusher from 'pusher-js';
type Item = Record<string, any>;
interface Bootstrap {user:Item;projects:Item[];conversations:Item[];connections:Item[];approvals:Item[];schedules:Item[];activity:Item[];artifacts:Item[];runs:Item[];preview:boolean;integration:Item;}
const props=defineProps<{initial:Bootstrap}>();
const state=ref<Bootstrap>(props.initial);
const section=ref('home');
const projectId=ref<string|null>(null);
const conversationId=ref<string|null>(null);
const messages=ref<Item[]>([]);
const conversationRuns=ref<Item[]>([]);
const prompt=ref('');
const busy=ref(false);
const loadingConversation=ref(false);
const mobileMenu=ref(false);
const contextOpen=ref(false);
const projectPreviewOpen=ref(false);
const syncingProject=ref<string|null>(null);
const viewerContextUsed=ref(false);
const previewArtifact=ref<Item|null>(null);
const modal=ref<string|null>(null);
const searchQuery=ref('');
const projectFilter=ref('');
const projectForm=ref({name:'',description:'',color:'violet',tenant_id:'',instructions:''});
const editingProject=ref<string|null>(null);
const newProjectPrompt=ref('');const projectDrafts=createProjectDrafts();
const formError=ref('');
const modalBusy=ref(false);
const toast=ref('');
const model=ref('');
const models=ref<Item[]>([]);
const horusForm=ref({email:'',password:'',otp:''});
const scheduleForm=ref({project_id:'',name:'Atualização diária',source_id:'',time:'03:00'});
const profileName=ref(state.value.user.name);
const composer=ref<HTMLTextAreaElement|null>(null);
const projectPickerSearch=ref<HTMLInputElement|null>(null);
const uploadInput=ref<HTMLInputElement|null>(null);
const messageList=ref<HTMLElement|null>(null);
let realtime:Echo<'reverb'>|undefined;
let refreshing=false;let lastSyncAt=0;
const bootstrapRequests=createRequestGuard();const conversationSelection=createRequestGuard();const createConversationOnce=createSingleFlight<string>();const projectFormRequests=createRequestGuard();
let poll:ReturnType<typeof setInterval>|undefined;
let toastTimer:ReturnType<typeof setTimeout>|undefined;
const nav=computed(()=>[...(state.value.user.must_change_password?[]:[{id:'home',label:'Criar com IA',icon:Sparkles},{id:'projects',label:'Meus projetos',icon:LayoutGrid},{id:'catalog',label:'Catálogo BI',icon:Database},{id:'connections',label:'Conexões',icon:Link2},{id:'refresh',label:'Atualização de dados',icon:CalendarClock},{id:'activity',label:'Atividade',icon:Activity}]),{id:'account',label:'Segurança da conta',icon:ShieldCheck},...(state.value.user.can_manage_users&&!state.value.user.must_change_password?[{id:'users',label:'Usuários e acessos',icon:UsersRound}]:[])]);
const suggestions=[{icon:ChartNoAxesCombined,title:'Criar um dashboard',description:'Dê forma aos seus indicadores',prompt:'Quero criar um dashboard. Me ajude a escolher os indicadores e as fontes de dados.'},{icon:TrendingUp,title:'Explorar meus dados',description:'Encontre respostas e oportunidades',prompt:'Quero explorar os dados disponíveis no meu tenant e identificar os principais indicadores.'},{icon:Layers3,title:'Melhorar um dashboard',description:'Evolua o que você já construiu',prompt:'Quero revisar um dashboard existente e melhorar a clareza dos indicadores e do layout.'}];
const currentProject=computed(()=>state.value.projects.find(p=>p.id===projectId.value));
watch(()=>currentProject.value?.source_ref,(after,before)=>{if(after!==before&&/^app:[1-9][0-9]*$/.test(after??'')){projectPreviewOpen.value=true;contextOpen.value=false;}});
const projectConversations=computed(()=>state.value.conversations.filter(c=>c.project_id===projectId.value));
const projectArtifacts=computed(()=>state.value.artifacts.filter(a=>a.project_id===projectId.value));
const openai=computed(()=>state.value.connections.find(c=>c.provider==='openai'));
const horus=computed(()=>state.value.connections.find(c=>c.provider==='horus'));
const tenants=computed<Item[]>(()=>horus.value?.metadata?.tenants??[]);
const pendingApprovals=computed(()=>state.value.approvals.filter(a=>a.status==='pending' && new Date(a.expires_at)>new Date()));
const activeRun=computed(()=>conversationRuns.value.find(r=>['queued','running','awaiting_approval','cancel_requested'].includes(r.status)));
const filteredProjects=computed(()=>state.value.projects.filter(p=>(p.name+' '+(p.description??'')).toLowerCase().includes(projectFilter.value.toLowerCase())));
const searchResults=computed(()=>state.value.projects.filter(p=>(p.name+' '+(p.description??'')).toLowerCase().includes(searchQuery.value.toLowerCase())));
const pageTitle=computed(()=>currentProject.value?.name??nav.value.find(n=>n.id===section.value)?.label??'Seu espaço de criação');
const greeting=computed(()=>{const hour=new Date().getHours();return hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';});
const connectedCount=computed(()=>state.value.connections.filter(c=>c.status==='connected').length);
const colors=['violet','mint','amber','blue','rose'];
function openArtifact(a:Item){if(a.metadata?.example&&a.kind==='dashboard_preview'){modal.value='preview';return;}if(['image/png','image/jpeg'].includes(a.mime)){previewArtifact.value=a;return;}if(a.path)windowOpen('/api/artifacts/'+a.id+'/download');else notify('Arquivo indisponível.');}
function attachmentLabel(a:Item){const e=a.metadata?.extraction;return ({queued:'Preparando conteúdo…',processing:'Interpretando arquivo…',ready:e?.truncated?'Conteúdo disponível com limites':'Disponível para a IA',empty:'Sem texto extraível',failed:'Falha ao interpretar'} as Record<string,string>)[e?.status]||'Arquivo anexado';}
async function syncProject(){
 const id=currentProject.value?.id;if(!id||syncingProject.value)return;syncingProject.value=id;
 try{const result=await api(`/projects/${id}/sync-resource`,'POST');if(projectId.value===id&&section.value==='project')notify(result.message);await refresh();}
 catch(e){if(projectId.value===id&&section.value==='project')notify((e as Error).message);}finally{if(syncingProject.value===id)syncingProject.value=null;}
}
function toggleProjectPreview(){projectPreviewOpen.value=!projectPreviewOpen.value;if(projectPreviewOpen.value)contextOpen.value=false;}
async function previewGenerated(artifact:Item){state.value.artifacts=[artifact,...state.value.artifacts.filter(item=>item.id!==artifact.id)];try{await refresh();}catch(e){notify((e as Error).message);}}
function notify(text:string){toast.value=text;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',5500);}
async function api<T=any>(path:string,method='GET',data?:unknown):Promise<T>{
 const isForm=data instanceof FormData;
 const headers:Record<string,string>={'Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??''};
 if(!isForm)headers['Content-Type']='application/json';
 const response=await fetch(appUrl('/api'+path),{method,headers,credentials:'same-origin',...(data===undefined?{}:{body:isForm?data:JSON.stringify(data)})});
 if(response.status===401){location.href=appUrl('/login');throw new Error('Sua sessão expirou.');}
 if(response.status===429){throw new Error('Muitas solicitações. Aguarde alguns instantes e tente novamente.');}
 if(response.status===419){throw new Error('Sua sessão expirou. Atualize a página.');}
 const result=await response.json().catch(()=>({message:'Não foi possível concluir a operação.'}));
 if(response.status===423&&result.requires_password_change){window.location.assign(appUrl('/app/account'));throw new Error(result.message);}
 if(!response.ok){throw new Error(result.errors?String(Object.values(result.errors).flat()[0]):result.message??'Falha na solicitação.');}return result;
}
async function openCatalogProject(id:string){await refresh();navigate('project',id);}
async function refresh(){const isCurrent=bootstrapRequests.next();const result=await api<Bootstrap>('/bootstrap');if(!isCurrent())return;const before=state.value.connections.find(c=>c.provider==='horus');const after=result.connections.find(c=>c.provider==='horus');if(before?.status==='connected'&&(after?.status!=='connected'||before.metadata?.session_generation!==after.metadata?.session_generation)){window.location.assign(appUrl('/app/connections'));return;}state.value=result;}
function routeFromPath(){if(state.value.user.must_change_password){section.value='account';return;}conversationSelection.invalidate();loadingConversation.value=false;const parts=localPath().replace(/^\/app\/?/,'').split('/');if(parts[0]==='project'&&parts[1]){section.value='project';prompt.value=projectDrafts.switchProject(projectId.value,parts[1],prompt.value);projectId.value=parts[1];loadProject();}else{section.value=nav.value.some(n=>n.id===parts[0])?parts[0]:'home';prompt.value=projectDrafts.switchProject(projectId.value,null,prompt.value);projectId.value=null;conversationId.value=null;}}
function navigate(target:string,id?:string){if(state.value.user.must_change_password&&target!=='account'){target='account';id=undefined;}conversationSelection.invalidate();loadingConversation.value=false;mobileMenu.value=false;section.value=target;prompt.value=projectDrafts.switchProject(projectId.value,id??null,prompt.value);projectId.value=id??null;conversationId.value=null;messages.value=[];conversationRuns.value=[];history.pushState({},'',appUrl(target==='project'?`/app/project/${id}`:target==='home'?'/app':`/app/${target}`));if(id)loadProject();}
async function loadProject(){const conversation=state.value.conversations.find(c=>c.project_id===projectId.value);if(conversation){await loadConversation(conversation.id);}}
async function loadConversation(id:string,quiet=false){
 if(quiet&&(loadingConversation.value||conversationId.value!==id))return;
 const targetProject=projectId.value;const isCurrent=quiet?conversationSelection.current():conversationSelection.next();
 if(!quiet){conversationId.value=id;messages.value=[];conversationRuns.value=[];loadingConversation.value=true;}
 try{const result=await api(`/conversations/${id}`);if(!isCurrent()||projectId.value!==targetProject||conversationId.value!==id)return;if(result.conversation.project_id!==targetProject)throw new Error('Esta conversa não está disponível no projeto selecionado.');messages.value=result.messages;conversationRuns.value=result.runs;if(result.conversation.model)model.value=result.conversation.model;if(activeRun.value){await nextTick();messageList.value?.scrollTo({top:messageList.value.scrollHeight,behavior:'smooth'});}}
 catch(e){if(!quiet&&isCurrent())notify((e as Error).message);}finally{if(!quiet&&isCurrent())loadingConversation.value=false;}
}

function openNew(initial=''){if(state.value.user.must_change_password){navigate('account');return;}projectFormRequests.invalidate();newProjectPrompt.value=initial;editingProject.value=null;projectForm.value={name:'',description:'',color:'violet',tenant_id:'',instructions:''};formError.value='';modal.value='project';if(initial)prompt.value=initial;}
function editProject(project:Item){projectFormRequests.invalidate();editingProject.value=project.id;projectForm.value={name:project.name,description:project.description??'',color:project.color,tenant_id:project.tenant_id??'',instructions:project.instructions??''};formError.value='';modal.value='project';}
async function saveProject(){const target=editingProject.value;const initialPrompt=newProjectPrompt.value;const isCurrent=projectFormRequests.next();modalBusy.value=true;formError.value='';try{const payload={...projectForm.value,tenant_id:projectForm.value.tenant_id||null};const result=await api(target?`/projects/${target}`:'/projects',target?'PATCH':'POST',payload);if(!target)projectDrafts.seed(result.project.id,initialPrompt);await refresh();if(!isCurrent()||modal.value!=='project')return;modal.value=null;if(!target){navigate('project',result.project.id);notify('Projeto criado. Seu espaço está pronto.');}else notify('Projeto atualizado.');}catch(e){if(isCurrent())formError.value=(e as Error).message;}finally{modalBusy.value=false;}}

async function archiveProject(){if(!currentProject.value)return;modalBusy.value=true;try{await api(`/projects/${currentProject.value.id}`,'PATCH',{status:'archived'});await refresh();modal.value=null;navigate('projects');notify('Projeto arquivado.');}catch(e){notify((e as Error).message);}finally{modalBusy.value=false;}}
async function send(){
 if(!prompt.value.trim()||busy.value||activeRun.value)return;
 const content=prompt.value;const targetProject=projectId.value;const selectedModel=model.value;
 if(!targetProject){openNew(content);return;}
 busy.value=true;
 try{const targetConversation=conversationId.value??await newConversation();if(!targetConversation)return;await api(`/conversations/${targetConversation}/messages`,'POST',{content,...(selectedModel?{model:selectedModel}:{})});projectDrafts.clearSent(targetProject,content);if(projectId.value===targetProject&&prompt.value===content)prompt.value='';if(projectId.value===targetProject&&conversationId.value===targetConversation){await loadConversation(targetConversation);await nextTick();messageList.value?.scrollTo({top:messageList.value.scrollHeight,behavior:'smooth'});}await refresh();}catch(e){notify((e as Error).message);}finally{busy.value=false;}
}
async function newConversation():Promise<string|null>{
 const targetProject=projectId.value;if(!targetProject)return null;
 const isCurrent=conversationSelection.next();conversationId.value=null;messages.value=[];conversationRuns.value=[];loadingConversation.value=true;
 try{const id=await createConversationOnce(targetProject,async()=>{const conversation=await api(`/projects/${targetProject}/conversations`,'POST');await refresh();return String(conversation.id);});if(projectId.value===targetProject&&isCurrent())await loadConversation(id);return id;}catch(e){if(isCurrent())notify((e as Error).message);return null;}finally{if(isCurrent())loadingConversation.value=false;}
}

async function cancelRun(){if(activeRun.value){await api(`/runs/${activeRun.value.id}/cancel`,'POST');await loadConversation(conversationId.value!);}}
function chooseSuggestion(text:string){prompt.value=text;nextTick(()=>composer.value?.focus());}
function markdown(text:string):string{return DOMPurify.sanitize(marked.parse(text,{async:false}) as string,{FORBID_TAGS:['img','svg','iframe','object','embed','video','audio','style','form'],FORBID_ATTR:['style']});}
function date(value:string){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(new Date(value));}
function shortDate(value:string){return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(value));}
function statusLabel(status:string){return ({queued:'Na fila',running:'Em execução',awaiting_approval:'Aguardando sua aprovação',completed:'Concluído',failed:'Requer atenção',cancel_requested:'Interrompendo',cancelled:'Interrompido',pending_validation:'Validação pendente',active:'Ativa',disconnected:'Não conectado',connected:'Conectado',draft:'Rascunho'} as Record<string,string>)[status]??status;}
async function openHomeContext(){if(horus.value?.status!=='connected'){openConnect('horus');return;}searchQuery.value='';modal.value='choose-project';await nextTick();projectPickerSearch.value?.focus();}
function chooseProject(id:string){modal.value=null;navigate('project',id);}
function openConnect(provider:string){formError.value='';if(provider==='openai'){if(state.value.integration.openai_configured){location.href=appUrl('/auth/openai');}else{modal.value='openai';}}else{modal.value='horus';}}
async function connectHorus(){modalBusy.value=true;formError.value='';try{await api('/connections/horus/login','POST',horusForm.value);horusForm.value={email:'',password:'',otp:''};window.location.assign(appUrl('/app/connections'));}catch(e){formError.value=(e as Error).message;horusForm.value.password='';horusForm.value.otp='';}finally{modalBusy.value=false;}}
async function disconnect(provider:string){modalBusy.value=true;try{const result=await api(`/connections/${provider}`,'DELETE');if(provider==='horus'){window.location.assign(appUrl('/app/connections'));return;}await refresh();modal.value=null;notify(result.message??'Conta desconectada.');}catch(e){notify((e as Error).message);}finally{modalBusy.value=false;}}
async function refreshHorus(){modalBusy.value=true;try{await api('/connections/horus/refresh','POST');await refresh();notify('Acessos do G-Analise atualizados.');}catch(e){notify((e as Error).message);}finally{modalBusy.value=false;}}
async function verifyChatGpt(){modalBusy.value=true;try{const result=await api('/connections/openai/verify','POST',model.value?{model:model.value}:{});await refresh();notify('IA validada com '+result.model+'. Resposta completa recebida.');}catch(e){notify((e as Error).message);}finally{modalBusy.value=false;}}
async function loadModels(){if(openai.value?.status!=='connected')return;try{const result=await api('/connections/openai/models');models.value=result.models??[];if(!model.value&&models.value.length)model.value=models.value[0].slug??models.value[0].id;}catch(e){notify((e as Error).message);}}
async function approve(approval:Item,decision:string){try{await api(`/approvals/${approval.id}/decide`,'POST',{decision,fingerprint:approval.fingerprint});await refresh();notify(decision==='approved'?'Autorização registrada para esta execução.':'Execução recusada.');}catch(e){notify((e as Error).message);}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!projectId.value){notify('Crie ou abra um projeto antes de anexar um arquivo.');return;}const body=new FormData();body.append('file',file);try{await api(`/projects/${projectId.value}/files`,'POST',body);await refresh();contextOpen.value=true;projectPreviewOpen.value=false;notify('Arquivo anexado. Preparando o conteúdo para a IA.');}catch(e){notify((e as Error).message);}finally{if(uploadInput.value)uploadInput.value.value='';}}
async function saveSchedule(){modalBusy.value=true;formError.value='';try{await api('/schedules','POST',scheduleForm.value);await refresh();modal.value=null;notify('Plano salvo. A agenda será indicada como ativa após validação no G-Analise.');}catch(e){formError.value=(e as Error).message;}finally{modalBusy.value=false;}}
async function saveProfile(){modalBusy.value=true;try{await api('/profile','PATCH',{name:profileName.value});await refresh();modal.value=null;notify('Preferências atualizadas.');}catch(e){notify((e as Error).message);}finally{modalBusy.value=false;}}
async function copy(text:string){try{await navigator.clipboard.writeText(text);notify('Texto copiado.');}catch{notify('Não foi possível acessar a área de transferência.');}}
function keydown(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key==='k'){event.preventDefault();modal.value='search';}if((event.metaKey||event.ctrlKey)&&event.key==='n'){event.preventDefault();openNew();}if(event.key==='Escape'){modal.value=null;mobileMenu.value=false;}}
async function syncActivity(){if(refreshing||document.hidden||Date.now()-lastSyncAt<2000)return;lastSyncAt=Date.now();refreshing=true;try{await refresh();if(conversationId.value)await loadConversation(conversationId.value,true);}finally{refreshing=false;}}
onMounted(()=>{const flash=usePage().props.flash as Item|undefined;if(flash?.error||flash?.success)notify(flash.error??flash.success);if(import.meta.env.VITE_REVERB_APP_KEY){(window as any).Pusher=Pusher;realtime=new Echo({broadcaster:'reverb',key:import.meta.env.VITE_REVERB_APP_KEY,wsHost:import.meta.env.VITE_REVERB_HOST??location.hostname,wsPath:import.meta.env.VITE_REVERB_PATH??'',wsPort:Number(import.meta.env.VITE_REVERB_PORT??8087),wssPort:Number(import.meta.env.VITE_REVERB_PORT??443),forceTLS:import.meta.env.VITE_REVERB_SCHEME==='https',enabledTransports:['ws','wss'],authEndpoint:appUrl('/broadcasting/auth'),auth:{headers:{'X-CSRF-TOKEN':csrfToken()}}});realtime.private(`users.${state.value.user.id}`).listen('.workspace.changed',()=>syncActivity().catch(()=>{}));}routeFromPath();window.addEventListener('popstate',routeFromPath);window.addEventListener('keydown',keydown);loadModels();poll=setInterval(async()=>{try{if(!document.hidden&&(state.value.runs.some(r=>['queued','running','awaiting_approval','cancel_requested'].includes(r.status))||state.value.artifacts.some(a=>a.kind==='attachment'&&['queued','processing'].includes(a.metadata?.extraction?.status))||state.value.approvals.some(a=>a.type==='manual'&&['approved','executing'].includes(a.status)))){await syncActivity();}}catch{}},1800);});
onUnmounted(()=>{bootstrapRequests.invalidate();conversationSelection.invalidate();projectFormRequests.invalidate();realtime?.disconnect();if(poll)clearInterval(poll);if(toastTimer)clearTimeout(toastTimer);window.removeEventListener('popstate',routeFromPath);window.removeEventListener('keydown',keydown);});
function csrfToken():string{return document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content??'';}
function windowOpen(path:string):void{window.open(appUrl(path),'_blank','noopener,noreferrer');}
</script>

<template>
<Head :title="pageTitle" />
<div class="workspace-shell">
 <div v-if="mobileMenu" class="sidebar-backdrop" @click="mobileMenu=false"></div>
 <aside class="sidebar" :class="{'is-open':mobileMenu}">
  <a class="brand" :href="appUrl('/app')" @click.prevent="navigate('home')"><img class="brand-logo" :src="appUrl('/brand/g-analise-icon.png')" alt=""><span class="brand-wordmark"><span class="brand-product">G-Analise <span class="brand-ai">IA</span></span><small>UM PRODUTO INOVADORA</small></span></a>
  <button class="new-chat-button" :disabled="state.user.must_change_password" @click="openNew()"><Plus :size="17"/> Novo projeto <span>⌘ N</span></button>
  <button class="sidebar-search" :disabled="state.user.must_change_password" @click="modal='search'"><Search :size="16"/><span>Buscar no seu espaço</span><kbd>⌘ K</kbd></button>
  <div class="nav-label">SEU WORKSPACE</div>
  <nav class="main-nav"><button v-for="item in nav" :key="item.id" :class="{active:section===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="18"/><span>{{item.label}}</span><span v-if="item.id==='projects'" class="nav-count">{{state.projects.length}}</span><span v-if="item.id==='connections' && connectedCount<2" class="nav-attention"></span></button></nav>
  <div class="nav-label projects-label">PROJETOS RECENTES <button aria-label="Criar projeto" :disabled="state.user.must_change_password" @click="openNew()"><Plus :size="15"/></button></div>
  <div class="recent-projects"><button v-for="project in state.projects.slice(0,5)" :key="project.id" :class="{selected:projectId===project.id}" @click="navigate('project',project.id)"><span class="project-dot" :class="project.color"></span><span>{{project.name}}</span><ChevronRight :size="13"/></button><p v-if="!state.projects.length" class="sidebar-empty">Seus projetos aparecerão aqui.</p></div>
  <div class="sidebar-bottom"><div class="cloud-note"><span class="cloud-note-icon"><Cloud :size="18"/></span><div><strong>Seu plano. Sua IA.</strong><p>Inteligência na OpenAI.<br>Seus dashboards no G-Analise.</p></div></div><button class="help-link" @click="modal='help'"><CircleHelp :size="17"/> Ajuda e primeiros passos <ArrowUpRight :size="14"/></button><button class="profile-button" @click="modal='profile'"><span class="avatar">{{state.user.name.slice(0,1)}}</span><span><strong>{{state.user.name}}</strong><small>Workspace Inovadora</small></span><Settings2 :size="16"/></button></div>
 </aside>
 <main class="workspace-main">
  <header class="topbar"><div class="breadcrumbs"><button class="mobile-toggle icon-button" aria-label="Abrir menu" @click="mobileMenu=true"><Menu :size="21"/></button><span class="workspace-breadcrumb">Meu workspace</span><ChevronRight :size="13"/><strong>{{section==='home'?'Criar com IA':pageTitle}}</strong></div><div class="topbar-right"><span v-if="state.preview" class="preview-pill"><span></span> Ambiente local</span><button class="icon-button help-header" aria-label="Ajuda" @click="modal='help'"><CircleHelp :size="19"/></button><span class="topbar-divider"></span><span class="bi-label"><img :src="appUrl('/brand/g-analise-icon.png')" alt="" class="bi-mini"> G-ANALISE BI</span></div></header>
  <div v-if="section==='home'" class="home-view">
   <div class="home-content"><div class="welcome-eyebrow"><span class="sparkle-tile"><Sparkles :size="18"/></span> UM NOVO JEITO DE CRIAR BI</div><p class="greeting">{{greeting}}, {{state.user.name==='Equipe Inovadora'?'Inovadora':state.user.name.split(' ')[0]}} <span class="greeting-sun">✦</span></p><h1>Suas ideias.<br><span>Seus próximos dashboards.</span></h1><p class="hero-description">Converse com a IA e transforme seus dados em dashboards<br class="desktop-break"> que fazem sentido para o seu negócio.</p>
    <div class="composer home-composer" :class="{focused:prompt.length}"><textarea ref="composer" v-model="prompt" rows="3" placeholder="Descreva o que você quer criar, explorar ou melhorar…" aria-label="Sua mensagem para a IA" @keydown.enter.exact.prevent="send"></textarea><div class="composer-footer"><button class="composer-context" @click="openHomeContext"><Database :size="15"/>{{horus?.status==='connected'?'Escolher um projeto':'Conectar meus dados'}}<ChevronDown :size="13"/></button><div class="composer-actions"><button class="icon-button" title="Anexar arquivo" @click="notify('Abra um projeto para anexar seus arquivos.')"><Paperclip :size="17"/></button><button class="send-button" :disabled="!prompt.trim()||busy" aria-label="Iniciar projeto com esta mensagem" @click="send"><ArrowUp :size="20"/></button></div></div></div>
    <div class="composer-caption"><ShieldCheck :size="13"/> Você revisa. Você decide o que publicar.<span>Enter para enviar</span></div>
    <div class="suggestion-grid"><button v-for="suggestion in suggestions" :key="suggestion.title" class="suggestion-card" @click="chooseSuggestion(suggestion.prompt)"><span class="suggestion-icon"><component :is="suggestion.icon" :size="20"/></span><strong>{{suggestion.title}}</strong><p>{{suggestion.description}}</p><ArrowUpRight :size="15" class="suggestion-arrow"/></button></div>
    <div class="recent-heading"><div><h2>Continue de onde parou</h2><span>Um espaço para cada ideia.</span></div><button class="text-button" @click="navigate('projects')">Ver todos os projetos <ArrowRight :size="14"/></button></div>
    <div class="project-grid"><button v-for="project in state.projects.slice(0,3)" :key="project.id" class="project-card" @click="navigate('project',project.id)"><div class="project-card-top"><span class="project-icon" :class="project.color"><ChartNoAxesCombined v-if="project.color==='violet'" :size="21"/><Wallet v-else-if="project.color==='mint'" :size="21"/><Layers3 v-else :size="21"/></span><span class="draft-tag">{{project.is_example?'Exemplo':'Rascunho'}}</span></div><h3>{{project.name}}</h3><p>{{project.description||'Uma nova ideia pronta para ganhar forma.'}}</p><div class="project-card-bottom"><span><Clock3 :size="12"/>{{shortDate(project.updated_at)}}</span><ArrowUpRight :size="17"/></div></button><button v-if="!state.projects.length" class="empty-project-card" @click="openNew()"><Plus :size="24"/><strong>Seu primeiro projeto</strong><span>Organize uma ideia e comece a criar.</span></button></div>
   </div><footer class="workspace-footer"><span><span class="footer-symbol">✳</span> Feito para quem transforma dados em decisões.</span><span>G-Analise IA <span class="footer-dot">·</span> Inovadora</span></footer>
  </div>
  <div v-else-if="section==='projects'" class="content-view"><div class="page-heading"><div><div class="section-eyebrow">SEU ESPAÇO DE CRIAÇÃO</div><h1>Meus projetos</h1><p>Organize suas ideias, conversas e dashboards em um só lugar.</p></div><button class="primary-button" @click="openNew()"><Plus :size="17"/> Novo projeto</button></div><div class="filter-toolbar"><div class="input-with-icon"><Search :size="16"/><input v-model="projectFilter" placeholder="Buscar projetos…" aria-label="Buscar projetos"></div><span>{{filteredProjects.length}} projetos</span></div><div class="project-grid all-projects"><button v-for="project in filteredProjects" :key="project.id" class="project-card" @click="navigate('project',project.id)"><div class="project-card-top"><span class="project-icon" :class="project.color"><LayoutDashboard :size="21"/></span><span class="draft-tag">{{project.is_example?'Exemplo':'Rascunho'}}</span></div><h3>{{project.name}}</h3><p>{{project.description||'Seu próximo dashboard começa aqui.'}}</p><div class="project-card-bottom"><span><MessageSquare :size="13"/>{{project.conversations_count}} conversas</span><ArrowUpRight :size="17"/></div></button></div><div v-if="!filteredProjects.length" class="empty-state"><FolderOpen :size="36"/><h3>Nenhum projeto por aqui</h3><p>Crie um projeto ou tente outra busca.</p><button class="primary-button" @click="openNew()">Criar projeto</button></div></div>
  <AccountSecurity v-else-if="section==='account'" :user="state.user" :suite-url="state.integration.suite_url" :request="api" @updated="refresh" @notice="notify"/><UsersManagement v-else-if="section==='users'&&state.user.can_manage_users" :current-user="state.user" :request="api" @updated="refresh" @notice="notify"/><BiCatalog v-else-if="section==='catalog'" :tenants="tenants" :connected="horus?.status==='connected'" :user-id="state.user.id" :role="state.user.role" :viewer-context-used="viewerContextUsed" :request="api" @viewer-session="viewerContextUsed=true" @project="openCatalogProject" @updated="refresh" @notice="notify" @connect="navigate('connections')"/>
  <div v-else-if="section==='connections'" class="content-view connections-view"><div class="page-heading"><div><div class="section-eyebrow">TUDO CONECTADO, DO SEU JEITO</div><h1>Conexões</h1><p>Traga sua inteligência e conecte os dados do seu negócio.</p></div><span class="soft-badge"><ShieldCheck :size="15"/> Acesso individual e protegido</span></div><div class="connection-grid"><article class="connection-card"><div class="connection-card-head"><span class="provider-icon openai-icon"><Sparkles :size="28"/></span><span class="connection-status" :class="{connected:openai?.status==='connected'}"><span></span>{{openai?.status==='connected'?'Conectado':'Não conectado'}}</span></div><h2>ChatGPT</h2><p>Use os modelos disponíveis no seu plano ChatGPT para criar e evoluir seus dashboards.</p><div class="provider-features"><span><Check :size="14"/> Inferência nos servidores da OpenAI</span><span><Check :size="14"/> Autenticação com a sua conta</span><span><Check :size="14"/> Sem chave de API do usuário</span></div><div v-if="openai?.status==='connected'" class="connected-account"><strong>{{openai.account_label}}</strong><span>{{openai.metadata?.plan_usage?'Uso do plano autorizado':'Conectado para identidade'}}</span></div><button v-if="openai?.status!=='connected'" class="provider-connect" @click="openConnect('openai')"><Sparkles :size="17"/> Continuar com ChatGPT <ArrowUpRight :size="15"/></button><div v-else class="provider-connected-actions"><button class="secondary-button full-width" :disabled="modalBusy" @click="verifyChatGpt"><LoaderCircle v-if="modalBusy" :size="15" class="spin"/><CheckCircle2 v-else :size="15"/>Testar IA</button><button class="secondary-button full-width" @click="modal='disconnect-openai'">Gerenciar conexão</button></div><p v-if="openai?.metadata?.verification?.completed" class="connection-verification"><CheckCircle2 :size="13"/> Inferência validada com {{openai.metadata.verification.model}}</p><AiPlanUsage :connected="openai?.status==='connected'" :account-key="openai?.id+':'+openai?.expires_at"  :request="api"/><p v-if="!state.integration.openai_configured" class="connection-footnote"><Clock3 :size="13"/> Aguardando configuração da integração oficial.</p></article><article class="connection-card"><div class="connection-card-head"><span class="provider-icon bi-provider"><img :src="appUrl('/brand/g-analise-icon.png')" alt="G-Analise BI"></span><span class="connection-status" :class="{connected:horus?.status==='connected'}"><span></span>{{horus?.status==='connected'?'Conectado':'Não conectado'}}</span></div><h2>G-Analise BI</h2><p>Encontre suas aplicações, consulte suas fontes e crie dashboards com suas permissões.</p><div class="provider-features"><span><Check :size="14"/> Seus tenants e suas mesas</span><span><Check :size="14"/> Permissões respeitadas em cada ação</span><span><Check :size="14"/> Dashboards e fontes integrados</span></div><div v-if="horus?.status==='connected'" class="connected-account"><strong>{{horus.account_label}}</strong><span>{{tenants.length}} tenants disponíveis</span></div><button v-if="horus?.status!=='connected'" class="provider-connect bi-connect" @click="openConnect('horus')"><Link2 :size="17"/> Conectar G-Analise BI <ArrowUpRight :size="15"/></button><button v-else class="secondary-button full-width" @click="refreshHorus"><RefreshCw :size="15" :class="{'spin':modalBusy}"/> Atualizar acessos</button><p class="connection-footnote"><ShieldCheck :size="13"/> A conexão usa o acesso do seu usuário.</p></article></div><div class="connection-explainer"><span><Cloud :size="25"/></span><div><h3>A inteligência fica na nuvem. O controle fica com você.</h3><p>A OpenAI processa as solicitações de IA. O G-Analise IA organiza seu trabalho e opera o G-Analise BI com as permissões que você já possui.</p></div></div><div v-if="tenants.length" class="tenants-section"><h2>Seus tenants</h2><div v-for="tenant in tenants" :key="tenant.id" class="tenant-row"><Database :size="18"/><strong>{{tenant.name}}</strong><span>#{{tenant.id}}</span><CheckCircle2 :size="16"/></div></div></div>
  <div v-else-if="section==='activity'" class="content-view"><div class="page-heading"><div><div class="section-eyebrow">TRANSPARÊNCIA EM CADA ETAPA</div><h1>Atividade</h1><p>Acompanhe alterações, execuções e decisões no seu workspace.</p></div><button class="secondary-button" @click="refresh"><RefreshCw :size="15"/> Atualizar</button></div><div v-if="pendingApprovals.length" class="approval-section"><h2>Aguardando sua revisão <span class="count-badge">{{pendingApprovals.length}}</span></h2><article v-for="approval in pendingApprovals" :key="approval.id" class="approval-card"><div><ShieldCheck :size="22"/><h3>{{approval.title}}</h3></div><p>{{approval.description}}</p><ApprovalReview :approval="approval" :tenants="tenants"/><div class="approval-actions"><button class="secondary-button" @click="approve(approval,'rejected')">Recusar</button><button class="primary-button" @click="approve(approval,'approved')"><Check :size="15"/> Autorizar esta execução</button></div></article></div><BiOperations :approvals="state.approvals" :projects="state.projects" :tenants="tenants" :request="api" @updated="refresh" @project="navigate('project',$event)"/><div class="activity-list"><article v-for="event in state.activity" :key="event.id" class="activity-row"><span class="activity-icon"><CheckCheck v-if="event.action.includes('approved')" :size="17"/><FolderOpen v-else-if="event.action.startsWith('project')" :size="17"/><Activity v-else :size="17"/></span><div><strong>{{event.summary}}</strong><span>{{event.action}}</span></div><time>{{date(event.created_at)}}</time></article><div v-if="!state.activity.length" class="empty-state"><Activity :size="34"/><h3>Seu histórico começa aqui</h3><p>As ações realizadas serão registradas nesta página.</p></div></div></div>
  <div v-else-if="section==='refresh'" class="content-view"><div class="page-heading"><div><div class="section-eyebrow">DADOS ATUAIS, DECISÕES MELHORES</div><h1>Atualização de dados</h1><p>Confira as fontes e acompanhe a atualização dos seus dashboards.</p></div><button class="primary-button" @click="formError='';modal='schedule'"><Plus :size="17"/> Planejar atualização</button></div><RefreshInspector :projects="state.projects" :request="api" @updated="refresh"/><div class="refresh-principles"><div><CalendarClock :size="21"/><strong>Pelo menos uma vez ao dia</strong><p>Cada dashboard deve ter suas fontes atualizadas.</p></div><div><Globe2 :size="21"/><strong>Horário de Brasília</strong><p>America/Sao_Paulo, de preferência na madrugada.</p></div><div><CheckCheck :size="21"/><strong>Sucesso confirmado</strong><p>Agenda ativa e execução concluída, verificadas.</p></div></div><div v-if="!state.schedules.length" class="empty-state bordered"><span class="empty-icon"><CalendarClock :size="30"/></span><h3>Suas atualizações aparecerão aqui</h3><p>Conecte o G-Analise BI e vincule as fontes a um projeto.<br>Fontes compartilhadas usam uma única agenda.</p><button class="secondary-button" @click="navigate('connections')">Configurar conexões <ArrowRight :size="15"/></button></div><div v-else class="schedule-list"><article v-for="schedule in state.schedules" :key="schedule.id" class="schedule-row"><span class="project-icon blue"><RefreshCw :size="20"/></span><div><strong>{{schedule.name}}</strong><p>{{schedule.source_id}} · {{schedule.metadata?.coverage?.schedules?.find((s:Item)=>s.covers_daily)?.frequency||'Diariamente às '+schedule.time}} · Brasília</p></div><span class="status-tag" :class="{success:schedule.active&&schedule.last_success_at}">{{schedule.active&&schedule.last_success_at?'Ativa · última carga concluída':'Validação pendente'}}</span></article></div><p class="muted-note"><ShieldCheck :size="14"/> Uma agenda só é exibida como verificada após confirmação no G-Analise. Cargas já mais frequentes são preservadas.</p></div>
  <div v-else-if="section==='project'&&currentProject" class="project-workspace" :class="{'has-visual-preview':projectPreviewOpen}"><div class="project-top"><div><span class="project-icon small" :class="currentProject.color"><LayoutDashboard :size="18"/></span><div><h2>{{currentProject.name}}</h2><p>{{currentProject.tenant_name||'Nenhum tenant vinculado'}} <span v-if="currentProject.is_example">· Projeto de exemplo</span></p></div></div><div><button v-if="currentProject.source_ref" class="secondary-button compact" :disabled="!!syncingProject||!!activeRun" title="Receber a versão atual do BI preservando edições locais pendentes" @click="syncProject"><LoaderCircle v-if="syncingProject===currentProject.id" :size="15" class="spin"/><RefreshCw v-else :size="15"/>Atualizar do BI</button><button class="secondary-button compact" @click="editProject(currentProject)"><Settings2 :size="15"/> Configurar</button><button class="secondary-button compact" :aria-pressed="projectPreviewOpen" @click="toggleProjectPreview"><Eye :size="15"/>Prévia</button><button class="icon-button" title="Arquivos e prévias" @click="contextOpen=!contextOpen;if(contextOpen)projectPreviewOpen=false"><PanelRight :size="19"/></button></div></div><div class="project-body"><div class="chat-column"><div class="conversation-tabs"><button v-for="c in projectConversations" :key="c.id" :class="{active:conversationId===c.id}" @click="loadConversation(c.id)"><MessageSquare :size="13"/><span>{{c.title}}</span></button><button class="new-conversation" title="Nova conversa" @click="newConversation"><Plus :size="16"/></button></div><div ref="messageList" class="messages-area"><div v-if="loadingConversation" class="chat-loading"><LoaderCircle :size="20" class="spin"/> Carregando conversa…</div><div v-else-if="!messages.length" class="conversation-empty"><span class="large-sparkle"><Sparkles :size="28"/></span><h2>Vamos construir algo útil?</h2><p>Descreva o dashboard que você imagina.<br>Você pode começar pelos indicadores que precisa acompanhar.</p><button @click="chooseSuggestion('Quais dados estão disponíveis e quais dashboards podemos criar com eles?')">Explorar os dados disponíveis <ArrowUpRight :size="14"/></button></div><template v-for="message in messages" :key="message.id"><div v-if="message.role==='user'" class="message user-message"><div>{{message.content}}</div></div><div v-else class="message assistant-message" :class="{'system-message':message.role==='system'}"><span class="assistant-avatar"><Sparkles :size="16"/></span><div class="message-content"><strong>{{message.role==='system'?'Sobre este projeto':'G-Analise IA'}}</strong><div class="markdown" v-html="markdown(message.content)"></div><div v-if="message.role==='assistant'&&message.status==='completed'" class="message-tools"><button class="icon-button" title="Copiar resposta" @click="copy(message.content)"><Copy :size="13"/></button></div></div></div></template><div v-if="activeRun" class="agent-progress"><LoaderCircle :size="16" class="spin"/>{{statusLabel(activeRun.status)}}<button v-if="activeRun.status==='awaiting_approval'" @click="navigate('activity')">Revisar solicitação <ArrowRight :size="13"/></button></div></div><div class="chat-composer-wrap"><div v-if="openai?.status!=='connected'||horus?.status!=='connected'" class="chat-connection-note"><Link2 :size="14"/><span>Conecte {{openai?.status!=='connected'?'o ChatGPT':''}}{{openai?.status!=='connected'&&horus?.status!=='connected'?' e ':''}}{{horus?.status!=='connected'?'o G-Analise BI':''}} para ativar a criação com dados reais.</span><button @click="navigate('connections')">Conectar <ArrowRight :size="13"/></button></div><div class="composer chat-composer"><textarea ref="composer" v-model="prompt" rows="2" placeholder="O que você quer criar neste projeto?" aria-label="Mensagem do projeto" @keydown.enter.exact.prevent="send"></textarea><div class="composer-footer"><div class="composer-actions"><button class="icon-button" title="Anexar arquivo" @click="uploadInput?.click()"><Paperclip :size="17"/></button><select v-if="models.length" v-model="model" class="model-select" aria-label="Modelo de IA"><option v-for="m in models" :key="m.slug||m.id" :value="m.slug||m.id">{{m.display_name||m.id}}</option></select><span v-else class="model-placeholder"><Sparkles :size="13"/>{{openai?.status==='connected'?'Plano ChatGPT':'ChatGPT não conectado'}}</span></div><button v-if="activeRun" class="send-button stop-button" aria-label="Interromper tarefa" @click="cancelRun"><Square :size="14"/></button><button v-else class="send-button" :disabled="!prompt.trim()||busy" aria-label="Enviar mensagem" @click="send"><LoaderCircle v-if="busy" :size="19" class="spin"/><ArrowUp v-else :size="20"/></button></div></div><AiPlanUsage compact :connected="openai?.status==='connected'" :account-key="openai?.id+':'+openai?.expires_at"  :request="api"/><p v-if="openai?.metadata?.plan_usage" class="chat-plan-usage">Usando seu plano ChatGPT · <a href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">Gerenciar uso</a></p><p class="chat-disclaimer">A IA pode cometer erros. Revise indicadores, fontes e alterações antes de publicar.</p></div></div><ProjectPreviewPane v-if="projectPreviewOpen" :key="currentProject.id" :project="currentProject" :artifacts="projectArtifacts" :request="api" @close="projectPreviewOpen=false" @inspect="openArtifact" @generated="previewGenerated"/><aside v-if="contextOpen" class="context-panel"><div class="context-heading"><strong>Contexto do projeto</strong><button class="icon-button" aria-label="Fechar painel" @click="contextOpen=false"><X :size="16"/></button></div><div class="context-section"><h3>FONTES DE DADOS</h3><div class="context-source"><Database :size="18"/><div><strong>{{currentProject.tenant_name||'G-Analise BI'}}</strong><span>{{currentProject.tenant_id?'Tenant #'+currentProject.tenant_id:'Vincule um tenant nas configurações'}}</span></div></div></div><div class="context-section"><h3>ARQUIVOS E PRÉVIAS <button @click="uploadInput?.click()"><Plus :size="14"/></button></h3><button v-for="artifact in projectArtifacts" :key="artifact.id" class="artifact-button" :title="artifact.metadata?.extraction?.message||artifact.name" @click="openArtifact(artifact)"><LayoutDashboard v-if="artifact.kind==='dashboard_preview'" :size="18"/><FileText v-else :size="18"/><span><strong>{{artifact.name}}</strong><small>{{artifact.metadata?.example?'Prévia ilustrativa':artifact.kind==='attachment'?attachmentLabel(artifact):artifact.kind==='dashboard_export'?'Prévia real · '+date(artifact.created_at):'Arquivo do projeto'}}</small></span><ArrowUpRight :size="13"/></button><p v-if="!projectArtifacts.length" class="context-empty">Arquivos e resultados aparecerão aqui.</p></div><div class="context-policy"><ShieldCheck :size="18"/><strong>Você tem o controle</strong><p>Alterações que precisam de autorização são apresentadas para sua revisão.</p></div></aside></div></div>
  <div v-else class="empty-state"><FolderOpen :size="35"/><h3>Projeto não encontrado</h3><p>Ele pode ter sido arquivado ou não estar disponível para seu usuário.</p><button class="secondary-button" @click="navigate('projects')">Voltar aos projetos</button></div>
 </main>
 <ArtifactPreview v-if="previewArtifact" :artifact="previewArtifact" :conversation-id="conversationId" @approved="refresh();notify('Imagem autorizada. Peça a análise na conversa.')" @close="previewArtifact=null"/>
 <input ref="uploadInput" type="file" class="sr-only" accept=".csv,.txt,.pdf,.xlsx,.json,.yaml,.yml,.md,.png,.jpg,.jpeg" @change="upload">
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><CheckCircle2 :size="18"/><span>{{toast}}</span><button aria-label="Fechar aviso" @click="toast=''"><X :size="15"/></button></div></Transition>
 <div v-if="modal" class="modal-backdrop" @click.self="modal=null"><section class="modal" :class="{'wide-modal':modal==='preview','search-modal':modal==='search'||modal==='choose-project','project-picker-modal':modal==='choose-project'}" role="dialog" aria-modal="true" :aria-label="modal==='project'?'Configurar projeto':modal==='choose-project'?'Escolher projeto':'Janela do G-Analise IA'"><button class="modal-close icon-button" aria-label="Fechar janela" @click="modal=null"><X :size="19"/></button>
  <template v-if="modal==='project'"><span class="modal-icon"><FolderOpen :size="24"/></span><h2>{{editingProject?'Configurações do projeto':'Uma ideia, um novo projeto'}}</h2><p class="modal-description">Organize suas conversas e dashboards em um espaço próprio.</p><form @submit.prevent="saveProject"><label>Nome do projeto<input v-model="projectForm.name" required maxlength="100" placeholder="Ex.: Indicadores comerciais" autofocus></label><label>Descrição <span>opcional</span><textarea v-model="projectForm.description" rows="2" placeholder="O que você quer acompanhar ou construir?"></textarea></label><label>Tenant G-Analise BI<select v-model="projectForm.tenant_id"><option value="">Vincular depois</option><option v-for="tenant in tenants" :key="tenant.id" :value="String(tenant.id)">{{tenant.name}}</option></select></label><p v-if="!tenants.length" class="field-help">Conecte o G-Analise BI para escolher entre seus tenants autorizados.</p><label>Identidade do projeto</label><div class="color-options"><button v-for="color in colors" :key="color" type="button" :class="[color,{chosen:projectForm.color===color}]" :aria-label="color" @click="projectForm.color=color"><Check v-if="projectForm.color===color" :size="16"/></button></div><details class="advanced-settings"><summary>Orientações para a IA</summary><textarea v-model="projectForm.instructions" rows="3" placeholder="Conceitos de negócio, indicadores ou preferências para este projeto."></textarea></details><div v-if="formError" class="form-error" role="alert"><AlertCircle :size="16"/>{{formError}}</div><div class="modal-footer"><button v-if="editingProject" type="button" class="danger-text" @click="modal='archive'"><Trash2 :size="14"/> Arquivar</button><button type="button" class="secondary-button" @click="modal=null">Cancelar</button><button class="primary-button" :disabled="modalBusy||!projectForm.name.trim()"><LoaderCircle v-if="modalBusy" class="spin" :size="16"/>{{editingProject?'Salvar alterações':'Criar projeto'}}<ArrowRight v-if="!modalBusy" :size="15"/></button></div></form></template>
  <template v-else-if="modal==='choose-project'"><h2>Escolha um projeto</h2><p class="modal-description">Abra um espaço para continuar suas conversas e dashboards.</p><div class="search-dialog-input"><Search :size="21"/><input ref="projectPickerSearch" v-model="searchQuery" placeholder="Busque pelo nome do projeto…" aria-label="Buscar um projeto para abrir"></div><div class="search-results"><button v-for="project in searchResults" :key="project.id" @click="chooseProject(project.id)"><span class="project-icon small" :class="project.color"><FolderOpen :size="17"/></span><span><strong>{{project.name}}</strong><small>{{project.tenant_name||project.description||'Tenant ainda não vinculado'}}</small></span><ArrowRight :size="17"/></button><p v-if="!searchResults.length" class="context-empty">{{state.projects.length?'Nenhum projeto encontrado. Tente outro nome.':'Você ainda não tem projetos. Crie o primeiro para começar.'}}</p></div><div class="modal-footer"><button class="secondary-button" @click="modal=null">Cancelar</button><button v-if="state.user.role!=='viewer'" class="primary-button" @click="openNew(prompt)"><Plus :size="15"/> Criar novo projeto</button></div></template>
  <template v-else-if="modal==='search'"><div class="search-dialog-input"><Search :size="21"/><input v-model="searchQuery" placeholder="Busque um projeto ou uma ideia…" aria-label="Buscar no workspace" autofocus></div><div class="search-results"><div class="nav-label">PROJETOS</div><button v-for="project in searchResults" :key="project.id" @click="navigate('project',project.id);modal=null"><span class="project-icon small" :class="project.color"><FolderOpen :size="17"/></span><span><strong>{{project.name}}</strong><small>{{project.description}}</small></span><ArrowUpRight :size="15"/></button><p v-if="!searchResults.length" class="context-empty">Nenhum projeto encontrado.</p></div><div class="search-footer"><kbd>esc</kbd> para fechar</div></template>
  <template v-else-if="modal==='openai'"><span class="modal-icon"><Sparkles :size="26"/></span><h2>Conectar sua conta ChatGPT</h2><p class="modal-description">O acesso será feito na página oficial da OpenAI. Sua senha não é solicitada pelo G-Analise IA.</p><div class="setup-pending"><Clock3 :size="21"/><div><strong>Integração aguardando configuração</strong><p>O administrador precisa configurar o aplicativo aprovado para Sign in with ChatGPT e o uso do plano. Assim que estiver disponível, você poderá conectar sua conta aqui.</p></div></div><div class="modal-feature"><Cloud :size="17"/>Os modelos são processados na OpenAI.</div><div class="modal-feature"><ShieldCheck :size="17"/>O uso respeita as permissões e limites da sua conta.</div><div class="modal-footer"><a class="text-button" href="https://developers.openai.com/siwc/token-sharing-open-source" target="_blank" rel="noopener noreferrer">Documentação oficial <ExternalLink :size="13"/></a><button class="primary-button" @click="modal=null">Entendi</button></div></template>
  <template v-else-if="modal==='horus'"><span class="modal-icon bi-modal-icon"><img :src="appUrl('/brand/g-analise-icon.png')" alt=""></span><h2>Conectar G-Analise BI</h2><p class="modal-description">Use sua conta G-Analise. A conexão respeita seus tenants, mesas e permissões.</p><div v-if="!state.integration.lumo_login_enabled" class="setup-pending"><Clock3 :size="21"/><div><strong>Conexão aguardando habilitação</strong><p>A instalação do Lumo e o método de autenticação devem ser configurados pelo administrador. Nenhuma sessão do seu computador é importada automaticamente.</p></div></div><form v-else @submit.prevent="connectHorus"><label>E-mail<input v-model="horusForm.email" type="email" required autocomplete="username" placeholder="seu.email@empresa.com.br"></label><label>Senha<input v-model="horusForm.password" type="password" required autocomplete="current-password"></label><label>Código de autenticação <span>se ativado na sua conta</span><input v-model="horusForm.otp" inputmode="numeric" autocomplete="one-time-code" maxlength="10"></label><p class="field-help">Sua senha é usada apenas para abrir a sessão no Lumo e não é armazenada. O administrador deve habilitar “Uso do Lumo CLI” no seu perfil.</p><div v-if="formError" class="form-error"><AlertCircle :size="16"/>{{formError}}</div><div class="modal-footer"><button type="button" class="secondary-button" @click="modal=null">Cancelar</button><button class="primary-button" :disabled="modalBusy"><LoaderCircle v-if="modalBusy" :size="16" class="spin"/>Conectar conta</button></div></form><div v-if="!state.integration.lumo_login_enabled" class="modal-footer"><button class="primary-button" @click="modal=null">Entendi</button></div></template>
  <template v-else-if="modal==='profile'"><span class="modal-icon"><Settings2 :size="25"/></span><h2>Seu workspace</h2><p class="modal-description">Preferências da sua conta no G-Analise IA.</p><form @submit.prevent="saveProfile"><label>Seu nome<input v-model="profileName" required maxlength="100" :disabled="state.user.auth_provider==='suite'"></label><label>E-mail<input :value="state.user.email" disabled></label><div class="account-details"><span>Perfil <strong>{{['owner','admin'].includes(state.user.role)?'Administrador':state.user.role==='viewer'?'Leitura':'Autor'}}</strong></span><span>Horário <strong>Brasília · America/Sao_Paulo</strong></span></div><div class="modal-footer"><button type="button" class="secondary-button" @click="modal=null">Cancelar</button><button class="primary-button" :disabled="modalBusy||state.user.auth_provider==='suite'">Salvar</button></div></form><form class="logout-form" :action="appUrl('/logout')" method="post"><input type="hidden" name="_token" :value="csrfToken()"><button><LogOut :size="15"/> Sair da conta</button></form></template>
  <template v-else-if="modal==='help'"><span class="modal-icon"><BookOpen :size="25"/></span><h2>Da ideia ao dashboard</h2><p class="modal-description">Seu espaço de criação com IA, integrado ao G-Analise BI.</p><ol class="help-steps"><li><span>1</span><div><strong>Conecte suas contas</strong><p>Autorize o ChatGPT e conecte seu acesso ao G-Analise BI.</p></div></li><li><span>2</span><div><strong>Crie um projeto e converse</strong><p>Escolha um tenant e descreva os indicadores que precisa.</p></div></li><li><span>3</span><div><strong>Revise antes de publicar</strong><p>Confira a prévia, os dados e as alterações propostas.</p></div></li><li><span>4</span><div><strong>Acompanhe a atualização</strong><p>Confirme as fontes, a agenda e o sucesso da carga.</p></div></li></ol><div class="modal-footer"><button class="secondary-button" @click="modal=null">Fechar</button><button class="primary-button" @click="modal=null;navigate('connections')">Configurar conexões <ArrowRight :size="15"/></button></div></template>
  <template v-else-if="modal==='schedule'"><span class="modal-icon"><CalendarClock :size="25"/></span><h2>Planejar atualização</h2><p class="modal-description">Prepare a agenda da fonte. A ativação depende de validação e execução bem-sucedida no G-Analise.</p><form @submit.prevent="saveSchedule"><label>Projeto<select v-model="scheduleForm.project_id" required><option value="" disabled>Selecione um projeto</option><option v-for="p in state.projects.filter(p=>p.tenant_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Nome<input v-model="scheduleForm.name" required maxlength="100"></label><label>Fonte G-Analise<input v-model="scheduleForm.source_id" required placeholder="flow:123"></label><label>Horário diário em Brasília<input v-model="scheduleForm.time" type="time" required></label><div v-if="formError" class="form-error">{{formError}}</div><div class="modal-footer"><button type="button" class="secondary-button" @click="modal=null">Cancelar</button><button class="primary-button" :disabled="modalBusy">Salvar plano</button></div></form></template>
  <template v-else-if="modal==='archive'"><span class="modal-icon"><FolderOpen :size="25"/></span><h2>Arquivar este projeto?</h2><p class="modal-description">Ele sairá da lista de projetos ativos. Esta ação não exclui recursos do G-Analise BI.</p><div class="modal-footer"><button class="secondary-button" @click="modal=null">Cancelar</button><button class="primary-button" :disabled="modalBusy" @click="archiveProject">Arquivar projeto</button></div></template>
  <template v-else-if="modal==='disconnect-openai'"><span class="modal-icon"><Unplug :size="25"/></span><h2>Conexão ChatGPT</h2><p class="modal-description">{{openai?.account_label}}. Ao desconectar, novas tarefas deixam de usar esta conta. A aplicação também tentará revogar a sessão renovável na OpenAI.</p><div class="modal-footer"><button class="secondary-button" @click="modal=null">Voltar</button><button class="primary-button" :disabled="modalBusy" @click="disconnect('openai')">Desconectar conta</button></div></template>
  <template v-else-if="modal==='preview'"><div class="preview-modal-head"><span class="project-icon violet"><LayoutDashboard :size="22"/></span><div><h2>{{currentProject?.name}}</h2><p>Prévia ilustrativa · dados de exemplo</p></div></div><div class="example-banner"><Eye :size="15"/>Esta prévia demonstra a experiência. Os valores são ilustrativos e não foram consultados no G-Analise.</div><div class="dashboard-demo"><div class="dashboard-demo-title"><div><span>VISÃO GERAL</span><h3>Desempenho comercial</h3></div><span class="dashboard-period"><CalendarClock :size="13"/> Últimos 30 dias</span></div><div class="metric-grid"><div v-for="metric in projectArtifacts.find(a=>a.kind==='dashboard_preview')?.metadata?.metrics??[]" :key="metric.label"><span>{{metric.label}}</span><strong>{{metric.value}}</strong><small><TrendingUp :size="12"/>{{metric.change}} <span>vs. período anterior</span></small></div></div><div class="demo-chart"><div><strong>Evolução da receita</strong><span><i></i> Receita</span></div><svg viewBox="0 0 680 190" role="img" aria-label="Gráfico ilustrativo de evolução da receita"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#8b7af3" stop-opacity=".25"/><stop offset="100%" stop-color="#8b7af3" stop-opacity="0"/></linearGradient></defs><path d="M0 30H680M0 80H680M0 130H680M0 180H680" stroke="#ececf3" stroke-dasharray="4 5"/><path d="M0 158C30 150 35 140 60 145S100 125 120 132S160 100 180 110S220 95 240 104S280 77 300 83S340 60 360 74S400 48 420 59S460 30 480 46S520 18 540 34S580 8 600 22S640 6 680 12L680 190H0Z" fill="url(#chartFill)"/><path d="M0 158C30 150 35 140 60 145S100 125 120 132S160 100 180 110S220 95 240 104S280 77 300 83S340 60 360 74S400 48 420 59S460 30 480 46S520 18 540 34S580 8 600 22S640 6 680 12" fill="none" stroke="#8170e8" stroke-width="3"/></svg><div class="chart-labels"><span>01 out</span><span>07 out</span><span>14 out</span><span>21 out</span><span>29 out</span></div></div></div><div class="modal-footer"><span class="muted-note">Conecte suas contas para criar com dados reais.</span><button class="primary-button" @click="modal=null">Fechar prévia</button></div></template>
 </section></div>
</div>
</template>

<style scoped>
.project-picker-modal{padding:30px}.project-picker-modal .search-dialog-input{padding:15px 0;margin:4px 0 12px}.project-picker-modal .search-results{padding:0;max-height:42vh}.project-picker-modal .modal-footer{margin-top:16px}@media(max-width:650px){.project-picker-modal{padding:24px}}
</style>
